// Set this workflow as the Error Workflow on every other workflow, so a
// failure anywhere lands here instead of each pipeline growing its own
// half-copied error branch that drifts out of sync.
// The dedupe_key is carried through so a failure can be tied back to the
// exact lead that caused it, not just to a node name.
const e = items[0].json;
const last = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'no message';
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';

return [{ json: {
  workflow: wf,
  node: last,
  message: String(msg).slice(0, 500),
  execution_url: (e.execution && e.execution.url) || null,
  dedupe_key: (e.execution && e.execution.data && e.execution.data.dedupe_key) || null,
  severity: /timeout|ECONNRESET|rate limit|429|503/i.test(msg) ? 'transient' : 'hard'
} }];
